# Normalize a few accidental non-Traditional forms in authored copy.
TRANS=str.maketrans({'独':'獨','项':'項','继':'繼','续':'續','凭':'憑','连':'連','构':'構'})
def compile_case(s):
 d=next(d for d in DOMAINS if d['id']==s['domain'])
 people=[];questions=[]
 for idx,(name,role,risk,rows,refs) in enumerate(s['people']):
  pid='p'+str(idx)
  people.append({'id':pid,'name':name,'role':role,'opening':rows[0][1],'rounds':[r[1] for r in rows],'evidenceIds':refs})
  for rnd,(q,a) in enumerate(rows,1):
   questions.append({'id':f'{pid}-{rnd}','suspectId':pid,'round':rnd,'question':q,'response':a,'keywords':[word for word in ('密碼','通知','權限','工單','授權','理賠','承保','核保','截圖','海報','官方','認可','原檔','見證','來源','查證') if word in q]})
   questions.append({'id':f'{pid}-{rnd}-source','suspectId':pid,'round':rnd,'question':f'你呢句說法，可以對照邊份記錄？','response':'可以一齊睇 '+ '、'.join(refs)+'。'+rows[rnd-1][1],'keywords':['記錄','證據','依據']})
 risk_idx=next(i for i,p in enumerate(s['people']) if p[2])
 return {'id':s['key'],'domain':s['domain'],'title':s['title'],'subtitle':s['subtitle'],'intro':s['intro'],'category':{'id':d['id'],'label':d['label'],'icon':d['icon']},'kicker':d['label']+' · 虛構推理','suspects':people,'questions':questions,'evidence':[{'id':f'E{i+1}','title':title,'body':body,'source':source+' · 本局教育劇本'} for i,(title,body,source) in enumerate(s['evidence'])],'hints':['先比較第一輪說法同原始記錄，毋須等到最後。','搵出邊句把有限資料講成肯定結論。','再留意對方見過完整記錄之後，有冇更正說法。'],'references':[({'title':'香港金管局：數碼 Key 睇緊啲','url':'https://www.hkma.gov.hk/media/chi/doc/key-functions/banking-stability/consumer-corner/Personal_Digital_Keys_Chi_Final.pdf'} if s['key']=='bank-screen' else REFS[s['domain']])],'final':{'culpritId':'p'+str(risk_idx),'headline':'呢位角色嘅關鍵說法，超出咗本局證據能夠支持嘅範圍。','chain':[{'id':f'E{ei+1}','title':s['evidence'][ei][0],'text':text} for i,text in enumerate(s['chain']) for ei in [([0,2,1][i] if s['key']=='bank-code' else i)]],'innocentExplanations':[{'suspectId':'p'+str(i),'evidenceIds':p[4],'text':p[3][0][1]+' 呢啲記錄只解釋本局說法，唔代表對人物作全面評價。'} for i,p in enumerate(s['people']) if not p[2]],'takeaway':s['takeaway']}}
if __name__=='__main__':
 (BASE/'fraud-domains.json').write_text(json.dumps(DOMAINS,ensure_ascii=False,indent=2))
 (BASE/'fraud-cases.json').write_text(json.dumps({s['key']:compile_case(s) for s in SPECS},ensure_ascii=False,indent=2).translate(TRANS))
